questions = {
    "What is the capital of France?": "Paris",
    "What is the capital of Germany?": "Berlin",
    "What is the capital of the UK?": "London"
}

def get_user_answer(question):
    """Prompts the user to enter an answer for a given question."""
    while True:
        user_answer = input(f"What is the answer to {question}? ").strip().lower()
        if user_answer in questions[question].lower():
            return user_answer
        else:
            print("That's not a valid answer. Please try again.")

def calculate_score():
    """Asks the user a series of questions and keeps track of the score."""
    score = 0
    for question, correct_answer in questions.items():
        user_answer = get_user_answer(question)
        if user_answer == correct_answer:
            print(f"You scored 1 out of 1.")
            score += 1
        else:
            print(f"The correct answer is {correct_answer}. You scored 0 out of 1.")

    print(f"Your final score is {score} out of 3.")

if __name__ == "__main__":
    calculate_score()
```

This program will ask the user a series of questions and keep track of the score. The user can enter the answers and the program will check if they match the correct answer. Finally, the program will print out the final score.
